                return '';
            let depth = 0;
            let inString = false;
            let escaped = false;
            for (let i = start; i < source.length; i += 1) {
                const ch = source[i];
                if (inString) {
                    if (escaped) {
                        escaped = false;
                    }
                    else if (ch === '\\') {
                        escaped = true;
                    }
                    else if (ch === '"') {
                        inString = false;
                    }
                    continue;
                }
                if (ch === '"') {
                    inString = true;
                    continue;
                }
                if (ch === startChar)
                    depth += 1;
